// Helper: Calculate FM Overall Rating (50-99) for player based on positional role weights
function calculatePlayerOvr(player, targetPos = null) {
    const pos = targetPos || player.pos;
    const s = player.stats;
    let score = 0;

    if (pos === 'GK') {
        score = (s.reflexes * 0.25) + (s.oneOnOnes * 0.20) + (s.handling * 0.18) + 
                (s.aerial * 0.14) + (s.positioning * 0.13) + (s.command * 0.10);
    } else if (pos === 'ST') {
        score = (s.finishing * 0.20) + (s.offTheBall * 0.15) + (s.composure * 0.14) + 
                (s.pace * 0.12) + (s.dribbling * 0.11) + (s.heading * 0.10) + 
                (s.technique * 0.10) + (s.strength * 0.08);
    } else if (pos === 'LW' || pos === 'RW' || pos === 'LM' || pos === 'RM') {
        score = (s.pace * 0.18) + (s.acceleration * 0.18) + (s.dribbling * 0.16) + 
                (s.technique * 0.12) + (s.crossing * 0.12) + (s.finishing * 0.10) + 
                (s.vision * 0.08) + (s.agility * 0.06);
    } else if (pos === 'CAM') {
        score = (s.vision * 0.20) + (s.passing * 0.18) + (s.technique * 0.15) + 
                (s.firstTouch * 0.14) + (s.decisions * 0.12) + (s.dribbling * 0.11) + 
                (s.longShots * 0.06) + (s.composure * 0.04);
    } else if (pos === 'CM') {
        score = (s.passing * 0.18) + (s.vision * 0.14) + (s.workRate * 0.14) + 
                (s.teamwork * 0.12) + (s.stamina * 0.12) + (s.tackling * 0.10) + 
                (s.firstTouch * 0.10) + (s.decisions * 0.10);
    } else if (pos === 'CDM') {
        score = (s.tackling * 0.20) + (s.positioning * 0.18) + (s.workRate * 0.14) + 
                (s.strength * 0.14) + (s.teamwork * 0.12) + (s.passing * 0.10) + 
                (s.anticipation * 0.08) + (s.stamina * 0.04);
    } else if (pos === 'CB') {
        score = (s.tackling * 0.20) + (s.marking * 0.18) + (s.positioning * 0.18) + 
                (s.heading * 0.14) + (s.jumping * 0.12) + (s.strength * 0.10) + 
                (s.bravery * 0.05) + (s.pace * 0.03);
    } else if (pos === 'LB' || pos === 'RB' || pos === 'LWB' || pos === 'RWB') {
        score = (s.pace * 0.18) + (s.tackling * 0.16) + (s.stamina * 0.15) + 
                (s.crossing * 0.14) + (s.acceleration * 0.12) + (s.workRate * 0.10) + 
                (s.positioning * 0.10) + (s.dribbling * 0.05);
    } else {
        score = 15;
    }

    // Scale 1-20 to 50-99
    const ovr = Math.round(50 + ((score - 5) / 15) * 49);
    return Math.max(50, Math.min(99, ovr));
}

// Attach OVR to all players on load
PLAYERS.forEach(p => {
    p.ovr = calculatePlayerOvr(p);
});

// Lookup maps
var PLAYER_MAP = {};
PLAYERS.forEach(p => { PLAYER_MAP[p.id] = p; });

var CLUB_MAP = {};
CLUBS.forEach(c => { CLUB_MAP[c.id] = c; });
